import sys

def main():
    data = sys.stdin.buffer.read().split(b'\n')
    sums = {}
    for line in data[1:]:
        p = line.split(b',')
        if len(p) < 3:
            continue
        c = p[1]
        v = round(float(p[2]) * 100)
        try:
            sums[c] += v
        except KeyError:
            sums[c] = v
    out = []
    for c in sorted(sums):
        s = sums[c]
        sign = '-' if s < 0 else ''
        s = abs(s)
        out.append(c.decode() + ',' + sign + '%d.%02d' % (s // 100, s % 100))
    sys.stdout.write('\n'.join(out) + '\n')

main()
